// Cheap phase attribution with no profiler: each phase logs separately.
fun Modifier.phaseProbe(tag: String) = this
  .layout { measurable, constraints ->
    Log.d("phase", "$tag measure")
    val placeable = measurable.measure(constraints)
    layout(placeable.width, placeable.height) {
      Log.d("phase", "$tag place")      // placement re-runs without measurement
      placeable.place(0, 0)
    }
  }
  .drawBehind { Log.d("phase", "$tag draw") }

@Composable
fun Header(scroll: ScrollState) {
  // Composition read: logs measure + place + draw on every frame of the scroll,
  // and the composable body re-runs too.
  Box(Modifier.offset(y = scroll.value.dp).phaseProbe("header"))

  // Layout read: body never re-runs, only "place" and "draw" appear.
  Box(Modifier.offset { IntOffset(0, scroll.value) }.phaseProbe("header"))
}

