// ❌ A read-only interface promises nothing about mutation
data class Article(val id: String, val tags: List<Tag>)

// ✅ A type the compiler knows is frozen
import kotlinx.collections.immutable.ImmutableList
import kotlinx.collections.immutable.toImmutableList

@Immutable
data class Article(val id: String, val tags: ImmutableList<Tag>)

class FeedViewModel : ViewModel() {
  // Convert once, where the data is built — not inside composition.
  private fun toUi(dto: ArticleDto) = Article(dto.id, dto.tags.toImmutableList())
}

// ❌ Lying to the compiler: `views` changes, nothing is snapshot state,
//    so the counter on screen freezes at its first value forever.
@Immutable
class BadCounter(var views: Int)

// ✅ An honest @Stable: the mutation goes through snapshot state
@Stable
class Counter {
  var views by mutableIntStateOf(0)
}

data class Article(val id: String, val tags: List<Tag>)   // unstable param

@Composable
fun Feed(articles: List<Article>) {
  LazyColumn {
    items(articles, key = { it.id }) { article ->
      // ❌ A new List instance per recomposition. Strong skipping compares
      //    unstable args with ===, so this NEVER skips.
      ArticleCard(tags = article.tags.map { it.copy(label = it.label.uppercase()) })

      // ✅ Same instance across recompositions -> the identity check passes.
      ArticleCard(tags = article.tags)
    }
  }
}

@Composable
fun ArticleCard(tags: List<Tag>, onClick: () -> Unit = {}) {
  // The lambda above is memoized by the compiler; wrapping it in
  // remember { { ... } } by hand adds nothing since strong skipping.

  // ❌ Skippable but still slow: this runs on every non-skipped composition.
  val label = tags.sortedBy { it.label }.joinToString()

  // ✅ Cached until the input really changes.
  val cached = remember(tags) { tags.sortedBy { it.label }.joinToString() }
  Text(cached)
}

