@Composable
fun CollapsingHeader(listState: LazyListState) {
  // ❌ Composition read: the body of CollapsingHeader — and everything it
  //    emits — re-runs on every scroll frame.
  Box(
    Modifier
      .offset(y = -listState.firstVisibleItemScrollOffset.dp)
      .background(Color.White)
  )

  // ✅ Layout read: the lambda runs in the placement pass. The body of
  //    CollapsingHeader does not re-run at all.
  Box(
    Modifier
      .offset { IntOffset(0, -listState.firstVisibleItemScrollOffset) }
      .drawBehind { drawRect(Color.White) }   // draw-phase read
  )

  // ✅ Cheapest for pure visual motion: only the render node is re-recorded.
  Box(
    Modifier.graphicsLayer {
      translationY = -listState.firstVisibleItemScrollOffset.toFloat()
      alpha = 1f - (listState.firstVisibleItemScrollOffset / 300f).coerceIn(0f, 1f)
    }
  )

  // ❌ The lambda form with the read hoisted out — back in composition,
  //    and no better than the first version.
  val y = listState.firstVisibleItemScrollOffset
  Box(Modifier.offset { IntOffset(0, y) })
}

// Your own composables get the same treatment:
@Composable fun Ticker(price: () -> String) = Text(price())   // caller's read

// ❌ Stale forever: `items` and `query` are parameters, not snapshot state,
//    so the closure keeps whatever was passed on the first composition.
@Composable
fun BadResults(items: List<Item>, query: String) {
  val filtered by remember { derivedStateOf { items.filter { it.matches(query) } } }
  ResultList(filtered)
}

// ✅ Keyed remember: recomputes exactly when an input changes.
@Composable
fun Results(items: List<Item>, query: String) {
  val filtered = remember(items, query) { items.filter { it.matches(query) } }
  ResultList(filtered)
}

// ✅ derivedStateOf where it earns its keep: the input changes every frame,
//    the output flips twice per session.
@Composable
fun ScrollToTop(listState: LazyListState) {
  val showButton by remember {
    derivedStateOf { listState.firstVisibleItemIndex > 0 }
  }
  AnimatedVisibility(showButton) { FloatingActionButton(onClick = {}) { /* ... */ } }
}

