  Banner()
  LazyColumn { items(rows) { RowContent(it) } }
}

// ✅ One lazy list, the banner is just another item.
LazyColumn {
  item(contentType = "banner") { Banner() }
  items(rows, key = { it.id }, contentType = { it::class }) { RowContent(it) }
}

