// A count you can read without the inspector, in any build:
// the array survives recomposition, SideEffect runs once per composition
// that was actually applied.
@Composable
fun LogRecompositions(tag: String) {
  val count = remember { IntArray(1) }
  SideEffect { Log.d("recompose", "$tag = ${++count[0]}") }
}

// ❌ The parent reads the scroll position in its body, so Header and Footer
//    are invalidated every frame — Header shows 300 recompositions, 0 skips.
@Composable
fun Screen(listState: LazyListState) {
  val offset = listState.firstVisibleItemScrollOffset
  Column {
    Header(alpha = 1f - offset / 300f)
    Feed(listState)
    Footer()
  }
}

// ✅ The read moves into the one place that needs it, and becomes a
//    draw-phase read at that. Header: 1 recomposition, Footer: 1.
@Composable
fun Screen(listState: LazyListState) {
  Column {
    Header(
      Modifier.graphicsLayer {
        alpha = 1f - (listState.firstVisibleItemScrollOffset / 300f).coerceIn(0f, 1f)
      }
    )
    Feed(listState)
    Footer()
  }
}

// A new lambda every frame: the compiler's memo is keyed on `progress`
@Composable
fun Player(progress: Float, onSeek: (Float) -> Unit) {
  Controls(onSkip = { onSeek(progress + 10f) })   // Controls never skips
}

// Stable identity, stale value: `progress` is frozen at first composition
@Composable
fun PlayerBroken(progress: Float, onSeek: (Float) -> Unit) {
  Controls(onSkip = remember { { onSeek(progress + 10f) } })
}

// One State object for the life of the call site, read at invocation time
@Composable
fun PlayerFixed(progress: Float, onSeek: (Float) -> Unit) {
  val currentProgress by rememberUpdatedState(progress)
  val currentOnSeek by rememberUpdatedState(onSeek)
  val onSkip = remember { { currentOnSeek(currentProgress + 10f) } }
  Controls(onSkip = onSkip)      // same instance every frame, so Controls skips
}

// Same trick keeps a long-lived effect from restarting on every new callback
@Composable
fun Splash(onTimeout: () -> Unit) {
  val latest by rememberUpdatedState(onTimeout)
  LaunchedEffect(Unit) {         // keyed on Unit: starts once
    delay(2_000)
    latest()                     // ...but invokes the newest callback
  }
}

// Two call sites: rotating disposes the player and builds a new one
@Composable
fun ScreenBroken(wide: Boolean, url: String) {
  if (wide) Row { Player(url); Details() }
  else Column { Player(url); Details() }
}

// One movable group the runtime relocates between the two parents
@Composable
fun Screen(wide: Boolean, url: String) {
  // parameterised overload: do not capture `url` in a keyless remember
  val player = remember { movableContentOf<String> { u -> Player(u) } }

  if (wide) Row { player(url); Details() }
  else Column { player(url); Details() }
}

@Composable
private fun Player(url: String) {
  val context = LocalContext.current
  val exo = remember { ExoPlayer.Builder(context).build() }  // survives the move
  DisposableEffect(exo) {
    exo.setMediaItem(MediaItem.fromUri(url)); exo.prepare()
    onDispose { exo.release() }                              // not re-run on move
  }
  AndroidView(factory = { PlayerView(it).apply { player = exo } })
}

