// composed: a composition group per usage, no equals, invalidates composition
fun Modifier.pulsingBorderSlow(color: Color) = composed {
  val alpha by rememberInfiniteTransition(label = "pulse")
    .animateFloat(0f, 1f, infiniteRepeatable(tween(800)), label = "alpha")
  drawBehind { drawRect(color.copy(alpha = alpha), style = Stroke(2f)) }
}

// Node: parameters in a comparable element, behaviour in a long-lived node
private data class PulsingBorderElement(val color: Color) :
  ModifierNodeElement<PulsingBorderNode>() {
  override fun create() = PulsingBorderNode(color)
  override fun update(node: PulsingBorderNode) {
    node.color = color                       // mutate, do not allocate
    node.invalidateDraw()                    // draw phase only
  }
  override fun InspectorInfo.inspectableProperties() {
    name = "pulsingBorder"
    properties["color"] = color
  }
}

private class PulsingBorderNode(var color: Color) : Modifier.Node(), DrawModifierNode {
  private val alpha = Animatable(0f)

  override fun onAttach() {
    coroutineScope.launch {                  // node lifetime, zero recomposition
      alpha.animateTo(1f, infiniteRepeatable(tween(800)))
    }
  }

  override fun ContentDrawScope.draw() {
    drawContent()
    drawRect(color.copy(alpha = alpha.value), style = Stroke(2f))  // read in draw
  }
}

fun Modifier.pulsingBorder(color: Color): Modifier = this then PulsingBorderElement(color)

// A SubcomposeLayout per row: composition moves into the measure pass
LazyColumn {
  items(posts, key = { it.id }) { post ->
    BoxWithConstraints {
      if (maxWidth > 600.dp) WideRow(post) else NarrowRow(post)
    }
  }
}

// Read the breakpoint once, above the list; give the list a content type
BoxWithConstraints {
  val wide = maxWidth > 600.dp
  LazyColumn {
    items(
      items = posts,
      key = { it.id },
      contentType = { if (wide) "wide" else "narrow" },   // slots reuse per type
    ) { post -> if (wide) WideRow(post) else NarrowRow(post) }
  }
}

// Constraints needed only for measurement -> Modifier.layout, no subcomposition
fun Modifier.halfWidth() = layout { measurable, constraints ->
  val placeable = measurable.measure(constraints.copy(maxWidth = constraints.maxWidth / 2))
  layout(placeable.width, placeable.height) { placeable.place(0, 0) }
}

// Parent sized to the tallest child: one extra measure pass, no extra composition
Row(Modifier.height(IntrinsicSize.Min)) {
  Text(long); VerticalDivider(); Text(short)
}

// Illegal: a Measurable may be measured only once per pass
Layout(content) { measurables, constraints ->
  val first = measurables[0].measure(constraints)
  val again = measurables[0].measure(constraints)   // throws
  layout(first.width, first.height) { first.place(0, 0) }
}

