class FeedScrollCompare {
  @get:Rule val rule = MacrobenchmarkRule()

  @Test fun noProfile() = scroll(CompilationMode.None())      // fresh-install case
  @Test fun withProfile() = scroll(CompilationMode.Partial()) // what users get

  private fun scroll(mode: CompilationMode) = rule.measureRepeated(
    packageName = "com.example.app",
    metrics = listOf(FrameTimingMetric()),
    compilationMode = mode,
    startupMode = StartupMode.COLD,
    iterations = 10,
  ) { startActivityAndWait(); flingFeed() }
}

