  @Test fun scroll() = rule.measureRepeated(
    packageName = "com.example.app",
    metrics = listOf(FrameTimingMetric()),        // frameDurationCpuMs, frameOverrunMs
    compilationMode = CompilationMode.Partial(),  // what a real install runs
    startupMode = StartupMode.WARM,
